# Atlas cache lab: stride 1
# Generated by gen_bench.py (E8). Deterministic, no input; ends by running off the end.
# One load sweep over a 1024-word array at stride 1 word(s): spatial locality.
# 'addi x0, x0, 0' lines are padding: the nh-nf pipeline has no hazard unit, so every
# register write is followed by 2 nops and all five models compute the same addresses.
    lui x5, 0x10             # x5 = array base 0x10000
    addi x0, x0, 0
    addi x0, x0, 0
    lui x7, 0x11            # x7 = end = base + 4096
    addi x0, x0, 0
    addi x0, x0, 0
    addi x10, x0, 1           # x10 = sweeps left
    addi x0, x0, 0
    addi x0, x0, 0
outer:
    addi x6, x5, 0           # x6 = pointer
    addi x0, x0, 0
    addi x0, x0, 0
loop:
    lw x9, 0(x6)             # the measured access
    addi x0, x0, 0
    addi x0, x0, 0
    add x8, x8, x6           # x8 = checksum of the addresses read
    addi x0, x0, 0
    addi x0, x0, 0
    addi x6, x6, 4          # stride 1 word(s)
    addi x0, x0, 0
    addi x0, x0, 0
    blt x6, x7, loop
    addi x10, x10, -1
    addi x0, x0, 0
    addi x0, x0, 0
    bne x10, x0, outer
